export const meta = {
  name: 'two-ok',
  description: 'Two trivial agents each return ok',
  phases: [{ title: 'Ok' }],
}
const results = await parallel([
  () => agent('Return exactly the word: ok. Do nothing else, use no tools.', {label: 'ok-1', phase: 'Ok'}),
  () => agent('Return exactly the word: ok. Do nothing else, use no tools.', {label: 'ok-2', phase: 'Ok'}),
])
return results
